/// The `value_src` vocabulary: where a column's value came from, and whether the description says it is
/// stored. A source the description does not list is `Unknown`; the description does not yet say what
/// its `is_stored` reports (rule r3, "Facts without a fallback"), and until it does, `false`.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum Source {
    /// The wire value `input`.
    Input,
    /// The wire value `default`.
    Default,
    /// The wire value `default_substituted`.
    DefaultSubstituted,
    /// The wire value `default_generated`.
    DefaultGenerated,
    /// The wire value `absent`.
    Absent,
    /// The wire value `materialized_input`.
    MaterializedInput,
    /// The wire value `skipped`.
    Skipped,
    /// The wire value `ephemeral_input`.
    EphemeralInput,
    /// The wire value `default_expr_unsupported`.
    DefaultExprUnsupported,
    /// The wire value `default_volatile_unresolved`.
    DefaultVolatileUnresolved,
    /// The wire value `default_pending`.
    DefaultPending,
    /// A value the description does not list, carrying its exact spelling (rule r3,
    /// spec/abi-v2/docs.md): a reader keeps it, for this field alone, and decodes on.
    Unknown(String),
}

impl Source {
    /// The wire spelling: the description's, or the raw value `Unknown` carries.
    pub fn as_str(&self) -> &str {
        match self {
            Source::Input => "input",
            Source::Default => "default",
            Source::DefaultSubstituted => "default_substituted",
            Source::DefaultGenerated => "default_generated",
            Source::Absent => "absent",
            Source::MaterializedInput => "materialized_input",
            Source::Skipped => "skipped",
            Source::EphemeralInput => "ephemeral_input",
            Source::DefaultExprUnsupported => "default_expr_unsupported",
            Source::DefaultVolatileUnresolved => "default_volatile_unresolved",
            Source::DefaultPending => "default_pending",
            Source::Unknown(raw) => raw.as_str(),
        }
    }

    /// Read one wire value. One the description does not list is `Unknown`,
    /// carrying it (rule r3): it never fails the document.
    pub fn from_wire(s: &str) -> Self {
        match s {
            "input" => Source::Input,
            "default" => Source::Default,
            "default_substituted" => Source::DefaultSubstituted,
            "default_generated" => Source::DefaultGenerated,
            "absent" => Source::Absent,
            "materialized_input" => Source::MaterializedInput,
            "skipped" => Source::Skipped,
            "ephemeral_input" => Source::EphemeralInput,
            "default_expr_unsupported" => Source::DefaultExprUnsupported,
            "default_volatile_unresolved" => Source::DefaultVolatileUnresolved,
            "default_pending" => Source::DefaultPending,
            _ => Source::Unknown(s.to_string()),
        }
    }

    /// Whether the description lists this value: false exactly for `Unknown`.
    pub fn is_known(&self) -> bool {
        !matches!(self, Source::Unknown(_))
    }

    /// The description's `is_stored` fact for this source; `false` for `Unknown` until the description
    /// says otherwise.
    pub fn is_stored(&self) -> bool {
        match self {
            Source::Input => true,
            Source::Default => true,
            Source::DefaultSubstituted => true,
            Source::DefaultGenerated => true,
            Source::Absent => true,
            Source::MaterializedInput => true,
            Source::Skipped => false,
            Source::EphemeralInput => false,
            Source::DefaultExprUnsupported => false,
            Source::DefaultVolatileUnresolved => false,
            Source::DefaultPending => false,
            Source::Unknown(_) => false,
        }
    }
}

